      ],
      "support_status": "SUFFICIENT",
      "rationale": "P012 specifies the sequence and distinction between reported and logged activity; P016 establishes its prospective status."
    }
  },
  "signal_basis": {
    "component_id": "C022.signal_basis",
    "value": "Link account and schedule events, record relevant handling and handoffs, document offline preparation through labeled customer reports, and inspect the resulting history for continuity and conflicting identities or versions.",
    "scope": "A bounded cohort of new accounts; retrospective reports and unknowns remain explicit, and gap clarification preserves the original record. These procedures seek the proposed signal rather than report completed findings.",
