      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans specify the collection and inspection procedures, cohort boundary, reporting distinctions, record preservation and prospective status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C022.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without an unresolved empirical relation."
    }
  },
  "rationale": "The claim identifies the proposed documentary continuity signal. The stated operation constructs and inspects precisely that sequence, so the assumed signal licenses the claim within its explicit prospective and reporting bounds.",
  "uncertainty": "No material uncertainty for this narrowly descriptive claim; it does not assert that the sequence has already been observed.",
